package com.jr12866.dartcoach.core

import com.google.gson.JsonArray
import com.google.gson.JsonObject
import com.google.gson.JsonParser
import java.io.File

/**
 * Reads the parity corpus.
 *
 * The corpus is generated by the Python implementation in the Windows repo
 * and checked in here. It is the specification the Kotlin port is held to:
 * every case says what the Python produced, and the Kotlin side has to
 * produce the same thing.
 *
 * The corpus lives at the repository root, outside this module, because
 * both repos share it. Gradle copies it into the build directory before the
 * tests run (see `syncParityCorpus` in build.gradle.kts), and the path
 * arrives as the `parity.corpus.dir` system property.
 */
object Corpus {

    /** Where the corpus was copied to, as a directory. */
    private val dir: File by lazy {
        val path = System.getProperty("parity.corpus.dir")
            ?: error(
                "parity.corpus.dir is not set. The Gradle build sets it; " +
                    "run the tests through Gradle rather than an IDE."
            )
        File(path)
    }

    /**
     * Every case in a corpus file.
     *
     * A missing file is an error rather than an empty list: a test that
     * passes because it had nothing to check is worse than no test.
     */
    fun cases(name: String): List<JsonObject> {
        val file = File(dir, name)
        require(file.isFile) {
            "The parity corpus is missing $name (looked in ${file.absolutePath}). " +
                "Generate it with:\n" +
                "  cd ../darts-coach-windows\n" +
                "  python tools/parity/parity_gen.py --out ../dart-coach-android/corpus"
        }
        val root = JsonParser.parseString(file.readText())
        val array = root.asJsonArray
        return (0 until array.size()).map { array.get(it).asJsonObject }
    }
}

/** Convenience accessors so the assertions read cleanly. */
fun JsonObject.str(key: String): String? =
    if (has(key) && !get(key).isJsonNull) get(key).asString else null

fun JsonObject.int(key: String): Int? =
    if (has(key) && !get(key).isJsonNull) get(key).asInt else null

fun JsonObject.bool(key: String): Boolean? =
    if (has(key) && !get(key).isJsonNull) get(key).asBoolean else null

fun JsonObject.intList(key: String): List<Int>? =
    if (has(key) && !get(key).isJsonNull) {
        val arr = get(key).asJsonArray
        (0 until arr.size()).map { arr.get(it).asInt }
    } else {
        null
    }

fun JsonObject.strList(key: String): List<String> =
    if (has(key) && !get(key).isJsonNull) {
        val arr = get(key).asJsonArray
        (0 until arr.size()).map { arr.get(it).asString }
    } else {
        emptyList()
    }

fun JsonArray.strings(): List<String> =
    (0 until size()).map { get(it).asString }